//! Branch-free batch `exp`, `erfc` and normal CDF over slices.
//!
//! Fast paths with documented tolerances, not replacements: the scalar
//! Cody functions in [`crate::special`] stay the default and every golden
//! uses them. Same algorithm, constants and operation order as the C++
//! twin `qp/vmath.hpp`, which documents the method and references
//! (Cody-Waite reduction with a degree-13 polynomial; erfc as
//! `t exp(-z^2 + g(t))`, `t = 2 / (2 + z)`, with a 26-term Chebyshev
//! series for `g` generated by `cpp/core/tools/gen_erfc_cheb.cpp`).
//!
//! Tolerances (checked by the tests): `exp_batch` within 2 ulp on
//! [-708, 709]; `erfc_batch` relative error <= 2e-15 on [-6, 26.5]
//! (measured 1.0e-15 against the Cody erfc); `norm_cdf_batch` absolute
//! error <= 4e-16 and relative <= 2e-15 for x >= -37 (measured 2.8e-16 and
//! 1.1e-15). Inputs must be finite.

const LOG2E: f64 = std::f64::consts::LOG2_E;
const LN2_HI: f64 = f64::from_bits(0x3FE6_2E42_FEE0_0000); // fdlibm ln2_hi
const LN2_LO: f64 = f64::from_bits(0x3DEA_39EF_3579_3C76); // fdlibm ln2_lo
const MAGIC: f64 = 6_755_399_441_055_744.0; // 1.5 * 2^52
const EXP_LO: f64 = -746.0;
const EXP_HI: f64 = 710.0;

#[inline]
fn pow2_int(k: f64) -> f64 {
    let bits = (k + MAGIC)
        .to_bits()
        .wrapping_sub(MAGIC.to_bits())
        .wrapping_add(1023);
    f64::from_bits(bits << 52)
}

/// Scalar kernel of [`exp_batch`].
#[inline]
#[must_use]
pub fn exp1(x: f64) -> f64 {
    let x = x.clamp(EXP_LO, EXP_HI);
    let n = (x * LOG2E + MAGIC) - MAGIC;
    let r = (x - n * LN2_HI) - n * LN2_LO;
    let mut p = 1.0 / 6_227_020_800.0;
    p = p * r + 1.0 / 479_001_600.0;
    p = p * r + 1.0 / 39_916_800.0;
    p = p * r + 1.0 / 3_628_800.0;
    p = p * r + 1.0 / 362_880.0;
    p = p * r + 1.0 / 40_320.0;
    p = p * r + 1.0 / 5_040.0;
    p = p * r + 1.0 / 720.0;
    p = p * r + 1.0 / 120.0;
    p = p * r + 1.0 / 24.0;
    p = p * r + 1.0 / 6.0;
    p = p * r + 0.5;
    p = p * r + 1.0;
    p = p * r + 1.0;
    let n1 = ((n * 0.5) + MAGIC) - MAGIC;
    let n2 = n - n1;
    (p * pow2_int(n1)) * pow2_int(n2)
}

const ERFC_T0: f64 = 2.0 / 29.0;
#[allow(clippy::excessive_precision, clippy::unreadable_literal)]
const ERFC_CHEB: [f64; 26] = [
    -0.610_740_152_366_562_3,
    0.605_358_446_343_444_6,
    0.013_897_604_733_136_879,
    -0.008_264_970_081_573_855,
    -0.000_541_970_783_184_368_5,
    0.000_288_573_298_956_414_9,
    1.564_486_797_942_406_4e-5,
    -1.380_327_297_749_353_2e-5,
    -4.201_553_336_471_894e-9,
    7.160_979_147_369_276e-7,
    -5.773_887_132_798_51e-8,
    -3.436_001_214_990_645e-8,
    6.758_373_460_170_305_5e-9,
    1.215_720_391_486_285_9e-9,
    -5.347_830_745_980_906e-10,
    -2.121_626_615_033_843e-12,
    3.115_547_370_872_301_4e-11,
    -4.306_530_772_182_21e-12,
    -1.130_117_633_046_760_8e-12,
    4.178_673_364_632_363_3e-13,
    -5.706_217_020_163_412e-15,
    -2.155_193_002_686_094e-14,
    4.126_991_852_643_549_5e-15,
    3.236_750_060_683_912_8e-16,
    -2.675_285_801_266_927_3e-16,
    4.442_010_181_991_001_8e-17,
];

/// Scalar kernel of [`erfc_batch`].
#[inline]
#[must_use]
pub fn erfc1(x: f64) -> f64 {
    let z = x.abs().min(28.0);
    let t = 2.0 / (2.0 + z);
    let u = (2.0 * t - 1.0 - ERFC_T0) / (1.0 - ERFC_T0);
    let (mut b1, mut b2) = (0.0, 0.0);
    for &c in ERFC_CHEB[1..].iter().rev() {
        let b0 = 2.0 * u * b1 - b2 + c;
        b2 = b1;
        b1 = b0;
    }
    let g = ERFC_CHEB[0] + u * b1 - b2;
    // Exact split z^2 = zs^2 + d (z + zs), zs = z on a 1/16 grid (Cody 1969).
    let zs = ((z * 16.0 + MAGIC) - MAGIC) * 0.0625;
    let d = z - zs;
    let r = t * exp1(-zs * zs) * exp1(g - d * (z + zs));
    if x < 0.0 {
        2.0 - r
    } else {
        r
    }
}

/// `out[i] = exp(x[i])` over the common length.
pub fn exp_batch(x: &[f64], out: &mut [f64]) {
    for (o, &v) in out.iter_mut().zip(x) {
        *o = exp1(v);
    }
}

/// `out[i] = erfc(x[i])` over the common length.
pub fn erfc_batch(x: &[f64], out: &mut [f64]) {
    for (o, &v) in out.iter_mut().zip(x) {
        *o = erfc1(v);
    }
}

/// `out[i] = N(x[i]) = erfc(-x[i] / sqrt 2) / 2` over the common length.
pub fn norm_cdf_batch(x: &[f64], out: &mut [f64]) {
    for (o, &v) in out.iter_mut().zip(x) {
        *o = 0.5 * erfc1(-v * std::f64::consts::FRAC_1_SQRT_2);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::special::erfc;

    fn rel(a: f64, b: f64) -> f64 {
        ((a - b) / b).abs()
    }

    #[test]
    fn exp_two_ulp() {
        let mut g = crate::rng::SplitMix64::new(9);
        let mut worst: f64 = 0.0;
        for _ in 0..100_000 {
            let x = -708.0 + 1417.0 * ((g.next_u64() >> 11) as f64 / 9_007_199_254_740_992.0);
            worst = worst.max(rel(exp1(x), x.exp()));
        }
        assert!(worst <= 4.5e-16, "{worst}");
        assert_eq!(exp1(0.0), 1.0);
        assert_eq!(exp1(-800.0), 0.0);
        assert!(exp1(800.0).is_infinite());
    }

    #[test]
    fn erfc_tolerance_against_cody() {
        let mut worst: f64 = 0.0;
        let mut x = -6.0;
        while x <= 26.5 {
            worst = worst.max(rel(erfc1(x), erfc(x)));
            x += 1.0 / 512.0;
        }
        assert!(worst <= 2e-15, "{worst}");
        assert_eq!(erfc1(30.0), 0.0);
        assert_eq!(erfc1(-30.0), 2.0);
    }

    #[test]
    fn norm_cdf_batch_matches_scalar() {
        let x: Vec<f64> = (0..(46 * 256)).map(|i| -37.0 + i as f64 / 256.0).collect();
        let mut y = vec![0.0; x.len()];
        norm_cdf_batch(&x, &mut y);
        for (&xi, &yi) in x.iter().zip(&y) {
            let r = 0.5 * erfc(-xi * std::f64::consts::FRAC_1_SQRT_2);
            assert!((yi - r).abs() <= 4e-16, "{xi}");
            assert!(rel(yi, r) <= 2e-15, "{xi}");
        }
    }
}
